package main

import (
	"html/template"
	"strings"
)

const styles = `<style>
:root{color-scheme:light;--ink:#193830;--muted:#6e827a;--line:#e3ebe6;--green:#245f4e;--deep:#153e35;--mint:#dcebe2;--gold:#d5ae70;--surface:#fff;--back:#f3f6f2}
[hidden]{display:none!important}*{box-sizing:border-box}body{margin:0;background:var(--back);color:var(--ink);font:14px/1.55 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}a{color:inherit;text-decoration:none}button,input,select{font:inherit}fieldset{border:0;padding:0;margin:0;min-width:0}button,a{ -webkit-tap-highlight-color:transparent}.shell{max-width:1440px;margin:auto;min-height:100vh;display:grid;grid-template-columns:210px minmax(0,1fr)}
.side{background:#fff;border-right:1px solid var(--line);padding:30px 22px;display:flex;flex-direction:column;gap:35px}.brand{display:flex;align-items:center;gap:11px;font-size:20px;font-weight:700;letter-spacing:.08em}.brand-icon{width:37px;height:37px;border-radius:12px;background:var(--deep);color:#f4f0df;display:grid;place-items:center;font-size:19px}.brand small{display:block;color:#9bac9f;font-size:9px;font-weight:600;letter-spacing:.18em}.nav-label{color:#a0afa5;font-size:11px;letter-spacing:.12em;padding:0 11px 9px}.nav-item{display:flex;align-items:center;gap:11px;border-radius:12px;padding:9px;color:#607b6d;font-weight:600;transition:background .18s,color .18s}.nav-item:hover{background:#f3f7f3;color:#285d48}.nav-item.active{background:linear-gradient(135deg,#edf6ef,#e5f0e8);color:#215c49;box-shadow:inset 0 1px 0 #fff,inset 0 0 0 1px #dcebe0}.nav-icon{position:relative;display:grid;place-items:center;width:31px;height:31px;flex:0 0 31px;border-radius:10px;color:#fff;border:1px solid #ffffff73;box-shadow:inset 0 1px 1px #ffffff9c,inset 0 -2px 4px #173e292b,0 2px 4px #244f3529}.nav-icon:after{content:"";pointer-events:none;position:absolute;inset:1px 1px 50%;border-radius:9px 9px 7px 7px;background:linear-gradient(#ffffff38,#ffffff00)}.nav-icon svg{width:19px;height:19px;position:relative;z-index:1;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;filter:drop-shadow(0 1px 1px #173f3455)}.icon-overview{background:linear-gradient(145deg,#79c39a,#347d5e)}.icon-recovery{background:linear-gradient(145deg,#86b8d6,#507d9d)}.icon-permissions{background:linear-gradient(145deg,#9bbba9,#527d6b)}.icon-tips{background:linear-gradient(145deg,#e9c785,#ba8749)}.icon-remote{background:linear-gradient(145deg,#83c1c0,#418b8e)}.icon-limit{background:linear-gradient(145deg,#b5afda,#7e78b0)}.icon-export{background:linear-gradient(145deg,#a6bcd2,#6f8da9)}.side-note{margin-top:auto;padding:15px;border-radius:14px;background:#f4f8f4;color:#779082;font-size:12px;line-height:1.7}
.main{padding:34px 46px 64px;min-width:0}.top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:27px}.eyebrow{text-transform:uppercase;letter-spacing:.16em;color:#9daea4;font-size:10px;font-weight:700}.top h1{font-size:24px;letter-spacing:.02em;margin:3px 0 0}.status{display:inline-flex;align-items:center;gap:7px;color:#436c59;background:#e8f3eb;border-radius:99px;padding:7px 11px;font-size:12px;font-weight:600}.dot{width:7px;height:7px;border-radius:50%;background:#63a57b}.hero{position:relative;overflow:hidden;background:linear-gradient(115deg,#19483b,#286b56);border-radius:20px;color:#f8faf3;padding:30px 34px;min-height:150px;display:flex;align-items:center;justify-content:space-between;gap:20px}.hero:after{content:"";position:absolute;right:40px;top:-110px;width:330px;height:330px;border:1px solid #ffffff25;border-radius:50%;box-shadow:0 0 0 38px #ffffff08,0 0 0 82px #ffffff07}.hero>*{position:relative;z-index:1}.hero .eyebrow{color:#a9caba}.hero h2{font-size:25px;margin:9px 0 5px;letter-spacing:.04em}.hero p{margin:0;color:#c2dace}.hero-glyph{font-size:64px;color:#d6b878;opacity:.9;margin-right:50px}.grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(260px,1fr);gap:20px;margin-top:22px}.grid.listgrid{grid-template-columns:minmax(0,1fr)}.card{background:var(--surface);border:1px solid #e9efea;box-shadow:0 6px 24px #284d3a08;border-radius:18px;padding:25px;margin-bottom:20px}.card-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:20px}.card-title{font-size:16px;margin:0;font-weight:700}.sub{color:var(--muted);font-size:12px;margin:5px 0 0;line-height:1.7}.pill{font-size:11px;border-radius:99px;padding:5px 9px;background:#edf5ef;color:#5d806a;white-space:nowrap}.label{display:block;font-weight:600;font-size:12px;margin:16px 0 7px}.field{width:100%;background:#f8faf8;border:1px solid #e0eae3;border-radius:10px;padding:11px 13px;color:var(--ink);outline:none}.field:focus{border-color:#6aa58a;box-shadow:0 0 0 3px #75b48f22}.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin-top:21px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:0;border-radius:10px;padding:10px 17px;background:var(--green);color:white;font-weight:600;cursor:pointer}.btn:hover{background:#194d3c}.btn:disabled{opacity:.55;cursor:wait}.btn.secondary{background:#eef4ef;color:#35644e}.btn.secondary:hover{background:#e1eee4}.empty{border:1px dashed #dbe8de;background:#fafcf9;border-radius:12px;color:#82968a;padding:18px;text-align:center;font-size:12px}.path{font:12px/1.6 ui-monospace,monospace;word-break:break-all;color:#426b56}.path-row{padding:12px 0;border-bottom:1px solid #eff3ef}.path-row:last-child{border:0}.tip{margin-top:15px;padding:12px 14px;border-radius:10px;background:#f5f8f5;color:#779083;font-size:12px}.warning{background:#fbf6e9;color:#8a6b3e}.check{display:flex;align-items:flex-start;gap:9px;margin-top:14px;font-size:12px;color:#725d39}.check input{margin-top:3px}.foot{font-size:11px;color:#a4b2a9;margin-top:16px}.tablewrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:930px}th,td{text-align:left;border-bottom:1px solid #edf2ee;padding:15px 12px;vertical-align:middle}th{font-size:11px;color:#8da297;font-weight:600;white-space:nowrap}td{font-size:13px}.table-name{font-weight:700;color:#245f4e}.small-btn{border:0;background:none;color:#37735a;cursor:pointer;font-size:12px;padding:4px}.status-paused{background:#f9f0de;color:#8a6b3e}.detail-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.metric{background:#f6f9f6;border:1px solid #edf3ee;border-radius:12px;padding:16px;min-width:0}.metric b{display:block;font-size:20px;color:#183d31;margin:6px 0;overflow-wrap:anywhere}.metric span{color:#738c7d;font-size:12px}.task-row{display:flex;gap:14px;align-items:baseline;margin:9px 0}.task-key{min-width:65px;color:var(--muted);font-size:12px}.task-value{min-width:0;overflow-wrap:anywhere}.task-details{margin-top:16px;padding-top:12px;border-top:1px solid var(--line)}.task-details summary{cursor:pointer;color:#4b8267;font-weight:600}.record{border-top:1px solid #edf2ee;padding:14px 0}.record:first-of-type{border-top:0}.record .actions{margin-top:10px}.result{white-space:pre-wrap;word-break:break-word;background:#f6f9f6;border:1px solid var(--line);border-radius:12px;padding:16px;font:12px/1.65 ui-monospace,monospace}.back{color:#4b8267;font-weight:600;font-size:13px}.message{margin-top:10px;color:#e8f4e9;white-space:pre-wrap;overflow-wrap:anywhere}.root-list{max-height:185px;overflow:auto}
@media(max-width:850px){.detail-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.shell{display:block}.side{padding:15px 20px;flex-direction:row;align-items:center;gap:20px;border-bottom:1px solid var(--line)}.side{flex-wrap:wrap}.side nav{display:flex;overflow-x:auto;width:100%;gap:4px}.side nav .nav-label{display:none}.side nav .nav-item{white-space:nowrap;flex-shrink:0}.side-note{display:none}.main{padding:26px 20px}.grid{grid-template-columns:1fr}.hero-glyph{font-size:45px;margin-right:6px}.hero{padding:25px}.hero h2{font-size:21px}}@media(max-width:600px){.two{grid-template-columns:1fr}.hero-glyph{display:none}.main{padding:22px 14px}.card{padding:20px}}
</style><script src="/app/cangzhou/assets/submit-guard.js" defer></script>`
const header = `<aside class="side"><div class="brand"><span class="brand-icon">舟</span><span>藏舟<small>SAFE HARBOR</small></span></div><nav><div class="nav-label">工作空间</div><a class="nav-item" href="/app/cangzhou/"><span class="nav-icon icon-overview" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3.5" y="4" width="17" height="16" rx="3"/><path d="M7 16v-3m5 3V8m5 8v-5"/></svg></span>备份概览</a><a class="nav-item" href="/app/cangzhou/recoveries"><span class="nav-icon icon-recovery" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 8.5V6a2 2 0 0 1 2-2h5l2 2h5a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2h-4"/><path d="M9 12a4 4 0 1 1-3.8 5.2M5 11.8v3h3"/></svg></span>备份恢复</a><a class="nav-item" href="/app/cangzhou/permissions"><span class="nav-icon icon-permissions" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 3.4 19 6v5.5c0 4-2.8 6.9-7 9-4.2-2.1-7-5-7-9V6z"/><rect x="9" y="10.5" width="6" height="5" rx="1"/><path d="M10.3 10.5V9a1.7 1.7 0 0 1 3.4 0v1.5"/></svg></span>目录权限</a><a class="nav-item" href="/app/cangzhou/tips"><span class="nav-icon icon-tips" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M8.5 16.1c-.3-1.4-2-2.4-2-5a5.5 5.5 0 0 1 11 0c0 2.6-1.7 3.6-2 5zM9 18.2h6M10.5 20h3"/><path d="M10 10.8a2.2 2.2 0 0 1 2.2-2.2"/></svg></span>使用提示</a><a class="nav-item" href="/app/cangzhou/webdav"><span class="nav-icon icon-remote" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M7 17.5h10a3.2 3.2 0 0 0 .2-6.4 5.3 5.3 0 0 0-10.2-1.2A3.8 3.8 0 0 0 7 17.5z"/><path d="M9 14.3h6m-3-3v6"/></svg></span>远程路径</a><a class="nav-item" href="/app/cangzhou/limits"><span class="nav-icon icon-limit" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 17a8 8 0 1 1 14 0"/><path d="M12 14.5 16 9m-4 5.5-1.5 1.5M8 18.5h8"/><path d="M6.8 12h.1m10.2 0h.1M12 6.6v.1"/></svg></span>备份限速</a><a class="nav-item" href="/app/cangzhou/export"><span class="nav-icon icon-export" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M5 14.5v3.2A2.3 2.3 0 0 0 7.3 20h9.4a2.3 2.3 0 0 0 2.3-2.3v-3.2"/><path d="M12 4v10m-3.4-3.3L12 14l3.4-3.3"/></svg></span>设置导出</a></nav><div class="side-note">把重要的东西妥善收藏，<br>在需要时，依然找得到。</div></aside>`

func navHeader(path string) string {
	return strings.Replace(header, `class="nav-item" href="/app/cangzhou/`+path+`"`, `class="nav-item active" href="/app/cangzhou/`+path+`"`, 1)
}

var funcs = template.FuncMap{"humanBytes": humanBytes, "statusLabel": statusLabel, "formatTime": formatTime}
var page = template.Must(template.New("page").Funcs(funcs).Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>藏舟 · 备份任务</title>` + styles + `<script src="/app/cangzhou/assets/live-refresh.js" defer></script></head><body data-live-busy="{{if .Busy}}true{{else}}false{{end}}"><div class="shell">` + navHeader("") + `<main class="main"><header class="top"><div><div class="eyebrow">YOUR BACKUP SPACE</div><h1>备份任务</h1></div><div class="actions" style="margin:0"><span id="live-home-status" class="status" data-live-region><span class="dot"></span>{{if .Busy}}正在{{.Activity}}{{else}}服务运行中{{end}}</span><a class="btn" href="/app/cangzhou/?new=1">＋ 新建任务</a></div></header><section class="hero"><div><div class="eyebrow">A SAFE PLACE FOR WHAT MATTERS</div><h2>重要的事，值得妥善收藏。</h2><p>每个任务独立配置源目录、目标仓库与计划。</p><div id="live-home-message" data-live-region>{{if .Message}}<div class="message">{{.Message}}</div>{{end}}{{if .Busy}}<div class="message">已等待 {{.Elapsed}} 秒{{if eq .Activity "连接仓库"}} · 最长等待 5 分钟{{end}}</div>{{end}}</div></div><div class="hero-glyph">⌁</div></section><div class="grid listgrid"><div>
<datalist id="authorized-roots">{{range .Roots}}<option value="{{.}}">{{end}}</datalist>
{{if .New}}<section class="card"><div class="card-head"><div><h2 class="card-title">新建备份任务</h2><p class="sub">为此任务选择独立的源目录、目标和计划。</p></div><span class="pill">新任务</span></div><form method="post" action="/app/cangzhou/setup"><fieldset id="live-setup-fieldset" data-live-disabled {{if .Busy}}disabled{{end}}><input type="hidden" name="csrf" value="{{.CSRF}}"><label class="label">任务名称</label><input class="field" required name="name" maxlength="40" placeholder="例如：照片、工作资料"><label class="label">① 备份源目录</label><input class="field" list="authorized-roots" required name="source" placeholder="选择或输入飞牛已授权目录"><p class="sub">请先在飞牛应用设置中授权源目录。</p><label class="label">② 选择已保存的远程路径</label>{{if .DAVs}}<select class="field" name="dav_id" required><option value="">请选择连接</option>{{range .DAVs}}<option value="{{.ID}}">{{.Name}} · {{.URL}}</option>{{end}}</select>{{else}}<div class="tip warning">请先<a class="back" href="/app/cangzhou/webdav?new=1">添加远程路径</a>。</div>{{end}}<label class="label">仓库子目录（可选）</label><input class="field" name="target_path" placeholder="例如：nas-a/photos"><p class="sub">相对于已保存的远程路径；新建仓库时将尝试自动创建不存在的子目录。留空使用连接地址本身。</p><label class="label">仓库操作</label><select class="field" name="mode"><option value="create">新建仓库</option><option value="connect">连接已有仓库</option></select><label class="label">仓库加密密码</label><input class="field" required type="password" name="repo_password" minlength="12" placeholder="至少 12 位，请单独妥善保存" autocomplete="new-password"><p class="sub">连接账号和证书选项使用所选的远程路径配置；仓库加密密码按任务填写。</p><label class="label">单任务上传限速（KiB/s，0 表示只使用全局设置）</label><input class="field" type="number" min="0" max="1048576" name="upload_limit_kib" value="0"><label class="label">③ 备份计划（小时）</label><input class="field" type="number" name="hours" min="0" max="720" value="24" required><p class="sub">默认每 24 小时；0 为手动。创建任务后不会立即自动备份。</p><div class="actions"><button id="live-setup-submit" data-live-region data-live-disabled class="btn" {{if not .DAVs}}disabled{{end}}>{{if .Busy}}连接中，请稍候…{{else}}创建任务 →{{end}}</button>{{if .Jobs}}<a class="btn secondary" href="/app/cangzhou/">取消</a>{{end}}</div></fieldset></form><p class="foot">自动备份需要在应用私有目录保存密码；设备管理员可读取。</p></section>{{end}}
<section class="card"><div class="card-head"><div><h2 class="card-title">任务列表</h2><p class="sub">每个任务独立设置源目录、仓库与计划。</p></div><span id="live-home-count" class="pill" data-live-region>共 {{.Total}} 项</span></div><form method="get" action="/app/cangzhou/"><div class="actions" style="margin:0 0 12px"><input class="field" style="max-width:300px" name="q" value="{{.Query}}" placeholder="搜索任务名称、目录或目标"><button class="btn secondary">搜索</button>{{if .Query}}<a class="back" href="/app/cangzhou/">清除</a>{{end}}</div></form><div class="tablewrap"><table><thead><tr><th>任务</th><th>源目录</th><th>目标仓库</th><th>状态</th><th>上次运行</th><th>下一次</th><th>操作</th></tr></thead><tbody id="live-home-jobs" data-live-region>{{range .Jobs}}<tr><td><a class="table-name" href="/app/cangzhou/task?job={{.ID}}">{{.Name}}</a></td><td><span class="path">{{.Source}}</span></td><td><span class="path">{{.URL}}</span></td><td>{{if .Paused}}<span class="pill status-paused">已暂停</span>{{else}}<span class="pill">{{statusLabel .LastStatus}}</span>{{end}}</td><td>{{formatTime .LastStarted}}</td><td>{{if .Paused}}已暂停{{else if eq .IntervalHours 0}}手动{{else}}{{formatTime .Next}}{{end}}</td><td><div class="actions" style="margin:0"><a class="back" href="/app/cangzhou/task?job={{.ID}}">详情</a><a class="back" href="/app/cangzhou/edit?job={{.ID}}">编辑</a><form method="post" action="/app/cangzhou/pause"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="job" value="{{.ID}}"><input type="hidden" name="action" value="{{if .Paused}}resume{{else}}pause{{end}}"><button class="small-btn">{{if .Paused}}恢复{{else}}暂停{{end}}</button></form><a class="back" href="/app/cangzhou/remove?job={{.ID}}">删除</a></div></td></tr>{{else}}<tr><td colspan="7"><div class="empty">{{if $.Query}}没有匹配的任务{{else}}还没有备份任务{{end}}</div></td></tr>{{end}}</tbody></table></div></section>
</div></div><p class="foot">藏舟 0.4.7 · 测试版</p></main></div></body></html>`))
var snapPage = template.Must(template.New("snap").Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>历史快照 · 藏舟</title>` + styles + `</head><body><div class="shell">` + navHeader("") + `<main class="main"><a class="back" href="/app/cangzhou/">← 返回备份任务</a><header class="top"><div><div class="eyebrow">SNAPSHOT HISTORY</div><h1>{{.Job.Name}} · 历史快照</h1></div></header><section class="card"><p class="sub">恢复到新的私有目录，不会覆盖原目录。</p>{{range .Snapshots}}<div class="record"><strong>{{.Start.Format "2006-01-02 15:04"}}</strong><p class="path">{{.Source.Path}}</p><div class="actions"><a class="btn secondary" href="/app/cangzhou/browse?job={{$.Job.ID}}&amp;id={{.Root.Obj}}">浏览文件</a><form method="post" action="/app/cangzhou/restore"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="job" value="{{$.Job.ID}}"><input type="hidden" name="id" value="{{.Root.Obj}}"><button class="btn">恢复此快照</button></form></div></div>{{else}}<div class="empty">还没有快照，完成首次备份后会显示在这里。</div>{{end}}</section></main></div></body></html>`))
var browsePage = template.Must(template.New("browse").Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>快照内容 · 藏舟</title>` + styles + `</head><body><div class="shell">` + navHeader("") + `<main class="main"><a class="back" href="/app/cangzhou/snapshots?job={{.JobID}}">← 返回历史快照</a><header class="top"><div><div class="eyebrow">SNAPSHOT CONTENTS</div><h1>快照内容</h1></div></header><section class="card"><p class="sub">逐级浏览快照目录；恢复操作在历史快照页面进行。</p><p class="path">当前位置：/{{.Path}}</p>{{if .Path}}<a class="back" href="/app/cangzhou/browse?job={{.JobID}}&amp;id={{.ID}}&amp;path={{.Parent | urlquery}}">← 上一级</a>{{end}}{{if .Directories}}<div class="root-list">{{range .Directories}}<div class="path-row"><a class="back" href="/app/cangzhou/browse?job={{$.JobID}}&amp;id={{$.ID}}&amp;path={{.Path | urlquery}}">📁 {{.Name}}</a></div>{{end}}</div>{{end}}<form method="get" action="/app/cangzhou/browse"><input type="hidden" name="job" value="{{.JobID}}"><input type="hidden" name="id" value="{{.ID}}"><label class="label">打开快照中的目录（相对路径）</label><input class="field" name="path" value="{{.Path}}" placeholder="例如：相册/旅行"><div class="actions"><button class="btn secondary">打开目录</button></div></form>{{if .Truncated}}<div class="tip warning">此目录的列表超过显示上限，仅显示前 4 MiB；可输入相对路径打开未显示的子目录。</div>{{end}}<pre class="result">{{.Text}}</pre></section></main></div></body></html>`))

var removePage = template.Must(template.New("remove").Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>移除任务 · 藏舟</title>` + styles + `</head><body><div class="shell">` + navHeader("") + `<main class="main"><a class="back" href="/app/cangzhou/">← 返回备份任务</a><header class="top"><h1>移除任务</h1></header><section class="card"><h2 class="card-title">确认移除「{{.Name}}」？</h2><p class="sub">目标仓库：<span class="path">{{.URL}}</span></p><div class="tip">仅从藏舟的任务列表移除，不会删除目标仓库或源文件。本地任务配置文件会保留。</div><form method="post" action="/app/cangzhou/remove"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="job" value="{{.ID}}"><input type="hidden" name="confirm" value="yes"><div class="actions"><button class="btn">确认移除</button><a class="btn secondary" href="/app/cangzhou/">取消</a></div></form></section></main></div></body></html>`))

var detailPage = template.Must(template.New("detail").Funcs(funcs).Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>任务详情 · 藏舟</title>` + styles + `<script src="/app/cangzhou/assets/live-refresh.js" defer></script></head><body data-live-busy="{{if .Busy}}true{{else}}false{{end}}"><div class="shell">` + navHeader("") + `<main class="main"><a class="back" href="/app/cangzhou/">← 返回任务列表</a><header class="top"><div><div class="eyebrow">BACKUP TASK</div><h1>{{.Job.Name}}</h1></div><span id="live-detail-status" class="status" data-live-region>{{if .Job.Paused}}已暂停{{else}}{{statusLabel .Job.LastStatus}}{{end}}</span></header><div id="live-detail-message" data-live-region>{{if .Message}}<div class="tip">{{.Message}}</div>{{end}}</div><div id="live-detail-progress" data-live-region>{{with .Progress}}<section class="card"><div class="card-head"><div><h2 class="card-title">备份进度</h2><p class="sub">数据为 Kopia 的处理进度，统计包含复用的文件；处理完成后仍需写入并提交快照。</p></div></div><div class="detail-grid"><div class="metric"><span>预计总大小</span><b style="font-size:15px">{{.Total}}</b></div><div class="metric"><span>已处理大小</span><b style="font-size:15px">{{.Processed}}</b></div><div class="metric"><span>持续时间</span><b style="font-size:15px">{{.Elapsed}}</b></div><div class="metric"><span>预计剩余时间</span><b style="font-size:15px">{{.Remaining}}</b></div></div><p class="sub">开始时间：{{formatTime .Started}}</p>{{if .KnownTotal}}<progress value="{{.Percent}}" max="100" style="width:100%;margin-top:16px;accent-color:#245f4e"></progress><p class="sub">预计 {{.Percent}}% · 任务完成以最终状态为准</p>{{else}}<progress style="width:100%;margin-top:16px;accent-color:#245f4e"></progress><p class="sub">正在估算，当前没有可靠的总量或剩余时间。</p>{{end}}</section>{{end}}</div><section id="live-detail-summary" class="card" data-live-region><div class="detail-grid"><div class="metric"><span>上一次运行</span><b style="font-size:15px">{{formatTime .Job.LastStarted}}</b><span>完成：{{formatTime .Job.LastFinished}}</span></div><div class="metric"><span>记录的运行次数</span><b>{{if .Job.TrackingSince.IsZero}}—{{else}}{{.Job.RunCount}}{{end}}</b><span>{{if .Job.TrackingSince.IsZero}}旧版本未记录{{else}}记录开始于 {{formatTime .Job.TrackingSince}}{{end}}</span></div><div class="metric"><span>仓库对象总大小</span><b>{{if .Job.RepoSizeKnown}}{{humanBytes .Job.RepoSizeBytes}}{{else}}—{{end}}</b><span>{{if .Job.RepoSizeKnown}}统计于 {{formatTime .Job.RepoSizeAt}}{{else}}尚未统计{{end}}</span></div><div class="metric"><span>下一次计划</span><b style="font-size:15px">{{if .Job.Paused}}已暂停{{else if eq .Job.IntervalHours 0}}手动运行{{else}}{{formatTime .Job.Next}}{{end}}</b><span>间隔 {{.Job.IntervalHours}} 小时</span></div></div>{{if .Job.RepoSizeError}}<div class="tip warning">仓库大小统计失败：{{.Job.RepoSizeError}}</div>{{end}}{{if .Job.LastError}}<div class="tip warning">上次运行：{{.Job.LastError}}</div>{{end}}{{if .Busy}}<div class="tip">正在{{.Activity}}，已等待 {{.Elapsed}} 秒。</div>{{end}}<div class="actions"><form method="post" action="/app/cangzhou/backup"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="job" value="{{.Job.ID}}"><button class="btn" {{if or .Busy .Job.Paused}}disabled{{end}}>立即备份</button></form><a class="btn secondary" href="/app/cangzhou/snapshots?job={{.Job.ID}}">历史快照</a><a class="btn secondary" href="/app/cangzhou/edit?job={{.Job.ID}}">编辑任务</a><form method="post" action="/app/cangzhou/pause"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="job" value="{{.Job.ID}}"><input type="hidden" name="action" value="{{if .Job.Paused}}resume{{else}}pause{{end}}"><button class="btn secondary">{{if .Job.Paused}}恢复任务{{else}}暂停任务{{end}}</button></form><a class="back" href="/app/cangzhou/remove?job={{.Job.ID}}">删除任务</a></div><p class="foot">暂停不终止已运行的备份；恢复后从当前时间重新计算计划。</p></section><section class="card"><div class="card-head"><div><h2 class="card-title">任务配置</h2><p class="sub">仓库大小是整个仓库的对象总字节数；共享仓库时不代表此任务独占空间。</p></div></div><div class="task-row"><span class="task-key">源目录</span><span class="path task-value">{{.Job.Source}}</span></div><div class="task-row"><span class="task-key">目标仓库</span><span class="path task-value">{{.Job.URL}}</span></div><form method="post" action="/app/cangzhou/measure"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="job" value="{{.Job.ID}}"><div class="actions"><button class="btn secondary" {{if .Busy}}disabled{{end}}>重新统计仓库大小</button></div></form></section></main></div></body></html>`))

var editPage = template.Must(template.New("edit").Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>编辑任务 · 藏舟</title>` + styles + `</head><body><div class="shell">` + navHeader("") + `<main class="main"><a class="back" href="/app/cangzhou/task?job={{.Job.ID}}">← 返回任务详情</a><header class="top"><div><div class="eyebrow">EDIT TASK</div><h1>编辑「{{.Job.Name}}」</h1></div></header><div class="grid"><div><section class="card"><div class="card-head"><div><h2 class="card-title">基本设置</h2><p class="sub">更改名称、源目录和备份间隔。</p></div></div><form method="post" action="/app/cangzhou/job"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="job" value="{{.Job.ID}}"><label class="label">任务名称</label><input class="field" required name="name" value="{{.Job.Name}}"><label class="label">源目录</label><input class="field" list="authorized" required name="source" value="{{.Job.Source}}"><datalist id="authorized">{{range .Roots}}<option value="{{.}}">{{end}}</datalist><label class="label">间隔（小时；0 为手动）</label><input class="field" type="number" min="0" max="720" name="hours" value="{{.Job.IntervalHours}}"><label class="label">单任务上传限速（KiB/s，0 表示只使用全局设置）</label><input class="field" type="number" min="0" max="1048576" name="upload_limit_kib" value="{{.Job.UploadLimitKiB}}"><div class="actions"><button class="btn">保存基本设置</button></div></form></section><section class="card"><div class="card-head"><div><h2 class="card-title">目标仓库连接</h2><p class="sub">成功连接新目标后才切换；失败时保留原连接。</p></div></div><form method="post" action="/app/cangzhou/reconnect"><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="job" value="{{.Job.ID}}"><label class="label">已保存的远程路径</label>{{if .DAVs}}<select class="field" required name="dav_id"><option value="">请选择连接</option>{{range .DAVs}}<option value="{{.ID}}" {{if eq .ID $.Job.DAVID}}selected{{end}}>{{.Name}} · {{.URL}}</option>{{end}}</select>{{else}}<div class="tip warning">请先<a class="back" href="/app/cangzhou/webdav?new=1">添加远程路径</a>。</div>{{end}}<label class="label">仓库子目录（相对于连接地址）</label><input class="field" name="target_path" value="{{.Job.TargetPath}}" placeholder="相对于远程路径的目录"><label class="label">仓库操作</label><select class="field" name="mode"><option value="connect">连接已有仓库</option><option value="create">新建仓库</option></select><label class="label">仓库密码</label><input class="field" type="password" name="repo_password" placeholder="留空保留现有密码"><div class="tip warning">切换目标后，任务历史快照将显示新仓库的内容，原仓库不会删除。</div><div class="actions"><button class="btn" {{if not .DAVs}}disabled{{end}}>验证并更新连接</button></div></form></section></div><div><section class="card"><h2 class="card-title">授权目录</h2>{{range .Roots}}<div class="path-row"><span class="path">{{.}}</span></div>{{else}}<div class="empty">暂无授权目录</div>{{end}}</section></div></div></main></div></body></html>`))

var davPage = template.Must(template.New("dav").Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>远程路径 · 藏舟</title>` + styles + `<script src="/app/cangzhou/assets/dav.js" defer></script><script src="/app/cangzhou/assets/live-refresh.js" defer></script></head><body data-live-busy="{{if .Busy}}true{{else}}false{{end}}"><div class="shell">` + navHeader("webdav") + `<main class="main"><header class="top"><div><div class="eyebrow">STORAGE CONNECTIONS</div><h1>远程路径</h1></div><a class="btn" href="/app/cangzhou/webdav?new=1">＋ 新建连接</a></header><div id="live-remote-message" data-live-region>{{if .Message}}<div class="tip">{{.Message}}</div>{{end}}{{if .Busy}}<div class="tip">正在{{.Activity}}，已等待 {{.Elapsed}} 秒；请稍候。</div>{{end}}</div>{{if or .New .Edit.ID}}<section class="card"><div class="card-head"><div><h2 class="card-title">{{if .Edit.ID}}编辑连接{{else}}新建连接{{end}}</h2><p class="sub">支持 WebDAV 和 SFTP，一个连接可以供多个任务使用。</p></div></div><form id="dav-form" method="post" action="/app/cangzhou/webdav/save"><fieldset id="live-remote-fieldset" data-live-disabled {{if .Busy}}disabled{{end}}><input type="hidden" name="csrf" value="{{.CSRF}}"><input type="hidden" name="id" value="{{.Edit.ID}}"><label class="label">连接名称</label><input class="field" required name="name" maxlength="40" value="{{.Edit.Name}}" placeholder="例如：家里的飞牛"><label class="label">连接方式</label><select class="field" name="protocol" id="remote-protocol"><option value="webdav" {{if ne .Edit.Protocol "sftp"}}selected{{end}}>WebDAV</option><option value="sftp" {{if eq .Edit.Protocol "sftp"}}selected{{end}}>SFTP</option></select><div data-remote="webdav"><label class="label">WebDAV 地址</label><input class="field" type="url" name="url" value="{{.Edit.URL}}" placeholder="http://192.168.1.10:5005/"></div><div data-remote="sftp"><div class="two"><div><label class="label">服务器主机</label><input class="field" name="host" value="{{.Edit.Host}}"></div><div><label class="label">端口</label><input class="field" type="number" name="port" min="1" max="65535" value="{{if .Edit.Port}}{{.Edit.Port}}{{else}}22{{end}}"></div></div><label class="label">SFTP 根目录（绝对路径）</label><input class="field" name="remote_path" value="{{.Edit.RemotePath}}" placeholder="/path/to/backup"><label class="label">服务器主机密钥（known_hosts 格式）</label><textarea class="field" name="known_hosts" rows="3" placeholder="主机名 ssh-ed25519 公钥">{{.Edit.KnownHosts}}</textarea><label class="label">私钥（可选，无口令）</label><textarea class="field" name="private_key" rows="4" placeholder="私钥认证时填写；编辑时留空保留原有凭据"></textarea></div><div class="two"><div><label class="label">用户名</label><input class="field" required name="user" value="{{.Edit.User}}" autocomplete="off"></div><div><label class="label">密码</label><input class="field" type="password" name="password" placeholder="{{if .Edit.ID}}留空保留现有密码{{end}}" autocomplete="new-password"></div></div><label class="check" data-remote="webdav"><input type="checkbox" name="insecure_tls" value="1" {{if .Edit.InsecureTLS}}checked{{end}}><span>HTTPS 跳过证书验证；无法确认目标设备身份。</span></label><div class="tip warning">HTTP 会明文传输账号和密码。测试只检查目录可访问，不写入文件，也不代表有写入权限。</div><div id="dav-test-result" class="tip" hidden role="status"></div><div class="actions"><button class="btn secondary" id="dav-test" type="button">测试连接</button><button class="btn" type="submit">保存连接</button><a class="back" href="/app/cangzhou/webdav">取消</a></div><noscript><p class="sub">启用 JavaScript 后可以在保存前测试连接。</p></noscript></fieldset></form></section>{{end}}<section id="live-remote-list" class="card" data-live-region><div class="card-head"><div><h2 class="card-title">已保存的连接</h2><p class="sub">修改地址或凭据会验证并同步更新所有关联任务；任一任务验证失败则全部保留原配置。</p></div></div>{{range .DAVs}}<div class="record"><strong>{{.Name}}</strong><p class="path">{{.URL}}</p><p class="sub">账号：{{.User}} {{if .InsecureTLS}}· 跳过 HTTPS 证书验证{{end}}</p><div class="actions"><a class="btn secondary" href="/app/cangzhou/webdav?edit={{.ID}}">编辑 / 测试</a><details><summary class="back">删除连接</summary><form method="post" action="/app/cangzhou/webdav/remove"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.ID}}"><input type="hidden" name="confirm" value="yes"><p class="sub">正在使用中的连接无法删除；远端数据不会删除。</p><button class="btn secondary" {{if $.Busy}}disabled{{end}}>确认删除</button></form></details></div></div>{{else}}<div class="empty">还没有保存的 远程路径</div>{{end}}</section></main></div></body></html>`))

var recoveriesPage = template.Must(template.New("recoveries").Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>备份恢复 · 藏舟</title>` + styles + `<script src="/app/cangzhou/assets/live-refresh.js" defer></script></head><body data-live-busy="{{if .Busy}}true{{else}}false{{end}}"><div class="shell">` + navHeader("recoveries") + `<main class="main"><header class="top"><div><div class="eyebrow">RESTORED FILES</div><h1>备份恢复</h1></div><div class="actions" style="margin:0"><a class="btn secondary" href="/app/cangzhou/">查看备份任务</a><a class="btn" href="/app/cangzhou/offline">离线恢复</a></div></header><div id="live-recoveries-message" data-live-region>{{if .Message}}<div class="tip">{{.Message}}</div>{{end}}</div><section id="live-recoveries-list" class="card" data-live-region><div class="card-head"><div><h2 class="card-title">已恢复文件</h2><p class="sub">恢复结果保存在应用私有目录，也可以下载 ZIP。</p></div></div>{{range .Restores}}<div class="record"><span class="path">{{.}}</span><div class="actions"><a class="btn secondary" href="/app/cangzhou/download?id={{.}}">下载 ZIP ↓</a></div></div>{{else}}<div class="empty">还没有恢复记录。可在备份任务的历史快照中选择恢复。</div>{{end}}<p class="foot">ZIP 不包含符号链接及特殊文件。</p></section></main></div></body></html>`))
var permissionsPage = template.Must(template.New("permissions").Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>目录权限 · 藏舟</title>` + styles + `</head><body><div class="shell">` + navHeader("permissions") + `<main class="main"><header class="top"><div><div class="eyebrow">DIRECTORY ACCESS</div><h1>目录权限</h1></div></header><section class="card"><div class="card-head"><div><h2 class="card-title">已授权目录</h2><p class="sub">由飞牛应用设置提供</p></div></div><div class="root-list">{{range .Roots}}<div class="path-row"><span class="path">{{.}}</span></div>{{else}}<div class="empty">暂无授权目录</div>{{end}}</div><div class="tip">在飞牛应用设置中调整授权。每次备份前会重新检查。</div></section></main></div></body></html>`))
var tipsPage = template.Must(template.New("tips").Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>使用提示 · 藏舟</title>` + styles + `</head><body><div class="shell">` + navHeader("tips") + `<main class="main"><header class="top"><div><div class="eyebrow">A LITTLE REMINDER</div><h1>使用提示</h1></div></header><section class="card"><div class="path-row">01　单独保存每个仓库的密码</div><div class="path-row">02　定期测试历史快照恢复</div><div class="path-row">03　独立配置目标端防误删保护</div></section></main></div></body></html>`))

var settingsExportPage = template.Must(template.New("settings-export").Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>设置导出 · 藏舟</title>` + styles + `<script src="/app/cangzhou/assets/live-refresh.js" defer></script></head><body data-live-busy="{{if .Busy}}true{{else}}false{{end}}"><div class="shell">` + navHeader("export") + `<main class="main"><header class="top"><div><div class="eyebrow">EXPORT SETTINGS</div><h1>设置导出</h1></div></header><div id="live-export-message" data-live-region>{{if .Message}}<div class="tip">{{.Message}}</div>{{end}}{{if .Importing}}<div class="tip">正在验证导入的任务连接，请稍候。</div>{{end}}</div><section class="card"><div class="card-head"><div><h2 class="card-title">导出本地设置</h2><p class="sub">下载任务和远程连接配置，便于保留和查阅。</p></div></div><form method="post" action="/app/cangzhou/export/download"><input type="hidden" name="csrf" value="{{.CSRF}}"><label class="check"><input type="checkbox" name="include_secrets" value="yes"><span>包含远程连接密码、SFTP 私钥和仓库密码</span></label><div class="tip warning">包含密码或私钥时，导出文件为明文，请妥善保管。默认不包含密码和私钥。</div><p class="sub">文件不包含备份数据、快照、运行历史或 Kopia 仓库连接文件。导入时会重新验证各任务连接。</p><div class="actions"><button class="btn">下载设置 JSON ↓</button></div></form></section><section class="card"><h2 class="card-title">导入本地设置</h2><p class="sub">导入会合并配置，相同编号的已有项目会跳过。任务连接全部验证成功后才会保存。</p><form method="post" enctype="multipart/form-data" action="/app/cangzhou/import"><input type="hidden" name="csrf" value="{{.CSRF}}"><label class="label">藏舟设置 JSON</label><input class="field" type="file" name="settings" accept=".json,application/json" required><div class="actions"><button class="btn secondary">选择文件并预览</button></div></form></section></main></div></body></html>`))

var importPreviewPage = template.Must(template.New("import-preview").Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>导入设置 · 藏舟</title>` + styles + `</head><body><div class="shell">` + navHeader("export") + `<main class="main"><header class="top"><div><div class="eyebrow">IMPORT SETTINGS</div><h1>预览导入设置</h1></div><a class="btn secondary" href="/app/cangzhou/export">返回</a></header><form method="post" action="/app/cangzhou/import/apply"><input type="hidden" name="csrf" value="{{.CSRF}}"><section class="card"><h2 class="card-title">远程连接</h2>{{range .DAVs}}<div class="record"><strong>{{.Name}}</strong><p class="path">{{.URL}}</p>{{if index $.ExistingDAVs .ID}}<p class="sub">编号已存在，将跳过并使用当前配置。</p>{{else}}<label class="label">连接密码（若文件已包含可留空）</label><input class="field" type="password" name="dav_{{.ID}}" autocomplete="new-password">{{if eq .Protocol "sftp"}}<label class="label">SFTP 私钥（使用私钥时填写；若文件已包含可留空）</label><textarea class="field" name="key_{{.ID}}" rows="4"></textarea>{{end}}{{end}}</div>{{else}}<div class="empty">文件中没有连接</div>{{end}}</section><section class="card"><h2 class="card-title">备份任务</h2>{{range .Jobs}}<div class="record"><strong>{{.Name}}</strong><p class="path">{{.Source}} → {{.URL}}</p>{{if index $.ExistingJobs .ID}}<p class="sub">编号已存在，将跳过。</p>{{else}}<label class="label">仓库密码（若文件已包含可留空）</label><input class="field" type="password" name="repo_{{.ID}}" autocomplete="new-password">{{end}}</div>{{else}}<div class="empty">文件中没有任务</div>{{end}}<label class="check"><input type="checkbox" name="import_global_limit" value="yes"><span>同时导入全局上传限速（{{.GlobalUploadKiB}} KiB/s），覆盖当前全局限速</span></label><div class="tip">任务会连接已有仓库。任一任务验证失败时，现有设置保持不变。</div><div class="actions"><button class="btn">验证并导入</button></div></section></form></main></div></body></html>`))

var offlineRestorePage = template.Must(template.New("offline").Funcs(funcs).Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>离线恢复 · 藏舟</title>` + styles + `<script src="/app/cangzhou/assets/live-refresh.js" defer></script></head><body data-live-busy="{{if .Busy}}true{{else}}false{{end}}"><div class="shell">` + navHeader("recoveries") + `<main class="main"><header class="top"><div><div class="eyebrow">OFFLINE RECOVERY</div><h1>离线恢复</h1></div><a class="btn secondary" href="/app/cangzhou/recoveries">返回备份恢复</a></header><div id="live-offline-message" data-live-region>{{if .Message}}<div class="tip">{{.Message}}</div>{{end}}</div>{{if .Session}}<section id="live-offline-session" class="card" data-live-region><div class="card-head"><div><h2 class="card-title">离线仓库快照</h2><p class="sub">仓库以只读方式打开，恢复结果保存在藏舟私有目录。</p></div></div>{{range .Session.Snapshots}}<div class="record"><strong>{{.Start.Format "2006-01-02 15:04"}}</strong><p class="path">{{.Source.Path}}</p><form method="post" action="/app/cangzhou/offline/restore"><input type="hidden" name="csrf" value="{{$.CSRF}}"><input type="hidden" name="id" value="{{.Root.Obj}}"><div class="actions"><button class="btn" {{if $.Busy}}disabled{{end}}>恢复此快照</button></div></form></div>{{else}}<div class="empty">仓库中没有快照</div>{{end}}<form method="post" action="/app/cangzhou/offline/close"><input type="hidden" name="csrf" value="{{.CSRF}}"><div class="actions"><button class="btn secondary" {{if .Busy}}disabled{{end}}>关闭离线仓库并清理临时文件</button></div></form></section>{{else}}<section class="card"><h2 class="card-title">选择飞牛上的仓库或 ZIP</h2><p class="sub">只能访问已授权的目录。请浏览并选择仓库文件夹或 ZIP 文件，也可以直接输入路径。</p><div class="actions">{{range .Roots}}<a class="btn secondary" href="/app/cangzhou/offline?path={{.}}">{{.}}</a>{{else}}<span class="sub">请先在飞牛应用设置中授权目录。</span>{{end}}</div>{{if .Path}}<p class="path">当前位置：{{.Path}}</p><div class="actions"><a class="back" href="/app/cangzhou/offline?path={{.Path}}&amp;pick={{.Path}}">选择此文件夹</a></div>{{range .Entries}}<div class="path-row">{{if .IsDir}}<a class="back" href="{{.OpenURL}}">📁 {{.Name}}</a>{{else}}<span class="path">{{.Name}}</span>{{end}} <a class="back" href="{{.PickURL}}">选择</a></div>{{else}}<div class="empty">此目录为空</div>{{end}}{{end}}<form method="post" action="/app/cangzhou/offline/open"><input type="hidden" name="csrf" value="{{.CSRF}}"><label class="label">仓库来源</label><select class="field" name="mode"><option value="directory">仓库目录</option><option value="archive">NAS 上的 ZIP 文件</option></select><label class="label">路径</label><input class="field" name="path" value="{{.Pick}}" required><label class="label">仓库密码</label><input class="field" type="password" name="password" required autocomplete="new-password"><div class="actions"><button id="live-offline-local" data-live-disabled class="btn" {{if .Busy}}disabled{{end}}>打开仓库</button></div></form></section><section class="card"><h2 class="card-title">从电脑上传仓库 ZIP</h2><p class="sub">上传及解压会占用藏舟所在存储空间；ZIP 最大 64 GiB，解压后最大 256 GiB。</p><form method="post" enctype="multipart/form-data" action="/app/cangzhou/offline/open"><input type="hidden" name="csrf" value="{{.CSRF}}"><label class="label">仓库密码</label><input class="field" type="password" name="password" required autocomplete="new-password"><label class="label">仓库 ZIP 文件</label><input class="field" type="file" name="archive" accept=".zip,application/zip" required><div class="actions"><button id="live-offline-upload" data-live-disabled class="btn" {{if .Busy}}disabled{{end}}>上传并打开</button></div></form></section>{{end}}</main></div></body></html>`))

var limitsSettingsPage = template.Must(template.New("limits").Parse(`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>备份限速 · 藏舟</title>` + styles + `</head><body><div class="shell">` + navHeader("limits") + `<main class="main"><header class="top"><div><div class="eyebrow">BACKUP SPEED</div><h1>备份限速</h1></div></header>{{if .Message}}<div class="tip">{{.Message}}</div>{{end}}<section class="card"><h2 class="card-title">全局上传限速</h2><p class="sub">对所有备份任务生效。任务若同时设置限速，使用两者中较低的值；运行中的备份会在下次启动时采用新设置。</p><form method="post" action="/app/cangzhou/limits/save"><input type="hidden" name="csrf" value="{{.CSRF}}"><label class="label">上传速度（KiB/s）</label><input class="field" type="number" name="upload_limit_kib" min="0" max="1048576" value="{{.Global}}" required><p class="sub">0 表示全局不限制；1024 KiB/s 约为 1 MiB/s。仅限制备份写入仓库的数据速率。</p><div class="actions"><button class="btn">保存限速</button></div></form></section></main></div></body></html>`))
